<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Katalog Sparepart — Motofix</title><script src="https://cdn.tailwindcss.com"></script><script>tailwind.config={theme:{extend:{colors:{brand:'#FF6B00',ink:'#0B0B0C',panel:'#1A1A1E'}}}}</script></head><body class="min-h-screen bg-ink text-white"><header class="sticky top-0 z-20 border-b border-white/10 bg-ink/90 backdrop-blur"><div class="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-3 px-5 py-4"><a href="{{ route('dashboard') }}" class="font-black">MOTOFIX <span class="text-brand">/ SPAREPART</span></a><div class="flex gap-2 text-sm"><a href="{{ route('spareparts.orders') }}" class="rounded-xl border border-white/15 px-4 py-2">Pesanan saya</a><a href="{{ route('dashboard') }}" class="rounded-xl border border-white/15 px-4 py-2">Dashboard</a></div></div></header><main class="mx-auto max-w-7xl px-5 py-9">@if(session('success'))<p class="mb-4 rounded-xl border border-emerald-500/30 bg-emerald-500/10 p-4 text-sm text-emerald-200">{{ session('success') }}</p>@endif@if($errors->any())<div class="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 p-4 text-sm text-red-200">@foreach($errors->all() as $error)<p>{{ $error }}</p>@endforeach</div>@endif<p class="text-xs font-bold tracking-[.25em] text-brand">PARTS & ACCESSORIES</p><h1 class="mt-2 text-3xl font-black sm:text-4xl">Sparepart untuk perjalananmu.</h1><p class="mt-3 max-w-2xl text-sm leading-6 text-zinc-400">Pilih jumlah barang, lihat estimasi total, lalu buat pesanan. Stok diperiksa ulang ketika pesanan disimpan.</p><form method="POST" action="{{ route('spareparts.checkout') }}" id="partsForm">@csrf<div class="mt-7 grid gap-5 lg:grid-cols-[1fr_320px]"><div><div class="mb-4 flex gap-3"><input id="searchPart" type="search" placeholder="Cari nama atau kategori..." class="w-full rounded-xl border border-white/10 bg-panel px-4 py-3 outline-none focus:border-brand"><select id="categoryFilter" class="rounded-xl border border-white/10 bg-panel px-3 py-3 text-sm"><option value="">Semua kategori</option>@foreach($parts->pluck('kategori')->unique() as $category)<option>{{ $category }}</option>@endforeach</select></div><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3" id="partsGrid">@forelse($parts as $part)<article class="part-card rounded-2xl border border-white/10 bg-panel p-5 transition hover:-translate-y-1 hover:border-brand/40" data-name="{{ strtolower($part->nama_sparepart) }}" data-category="{{ $part->kategori }}"><div class="grid h-28 place-items-center rounded-xl bg-black/20 text-4xl">{{ str_contains(strtolower($part->kategori),'oli')?'🛢️':(str_contains(strtolower($part->kategori),'ban')?'🛞':'⚙️') }}</div><p class="mt-4 text-xs text-brand">{{ $part->kategori }}</p><h2 class="mt-1 font-bold">{{ $part->nama_sparepart }}</h2><p class="mt-2 text-lg font-black">Rp {{ number_format($part->harga,0,',','.') }}</p><p class="mt-1 text-xs text-zinc-500">Stok: {{ $part->stok }}</p><label class="mt-4 block text-xs text-zinc-400">Jumlah<input type="number" name="items[{{ $part->id }}]" min="0" max="{{ min(99,$part->stok) }}" value="0" data-price="{{ $part->harga }}" data-title="{{ $part->nama_sparepart }}" class="qty mt-2 w-full rounded-xl border border-white/10 bg-black/20 px-3 py-2.5 text-sm text-white outline-none focus:border-brand"></label></article>@empty<div class="rounded-2xl border border-white/10 p-6 text-sm text-zinc-400">Belum ada sparepart tersedia.</div>@endforelse</div></div><aside class="h-fit rounded-2xl border border-white/10 bg-panel p-5 lg:sticky lg:top-24"><h2 class="text-lg font-black">Ringkasan pesanan</h2><div id="cartLines" class="mt-4 space-y-3 text-sm"><p class="text-zinc-500">Belum ada barang dipilih.</p></div><div class="mt-5 border-t border-white/10 pt-4"><p class="text-xs text-zinc-500">Total estimasi</p><p id="cartTotal" class="mt-1 text-2xl font-black text-brand">Rp 0</p></div><label class="mt-5 block text-sm">Metode pembayaran<select name="payment_method" required class="mt-2 w-full rounded-xl border border-white/10 bg-black/20 px-3 py-3 text-sm outline-none focus:border-brand"><option value="tunai">Tunai di bengkel</option><option value="qris">QRIS</option><option value="transfer_bank">Transfer bank</option><option value="debit">Kartu debit</option></select></label><p class="mt-3 text-xs leading-5 text-zinc-500">Metode digital hanya dicatat, belum memproses pembayaran otomatis.</p><button class="mt-5 w-full rounded-xl bg-brand px-4 py-3 font-black text-black transition hover:-translate-y-0.5 hover:bg-orange-400">Buat pesanan →</button><a href="{{ route('spareparts.orders') }}" class="mt-3 block text-center text-xs font-bold text-brand">Lihat pesanan sebelumnya</a></aside></div></form></main><script>
const search=document.getElementById('searchPart'),filter=document.getElementById('categoryFilter');function filterParts(){const q=search.value.toLowerCase();document.querySelectorAll('.part-card').forEach(card=>card.classList.toggle('hidden',!(card.dataset.name.includes(q)||card.dataset.category.toLowerCase().includes(q))||(filter.value&&card.dataset.category!==filter.value)))}search.addEventListener('input',filterParts);filter.addEventListener('change',filterParts);const money=n=>'Rp '+new Intl.NumberFormat('id-ID').format(n);function updateCart(){let total=0,lines=[];document.querySelectorAll('.qty').forEach(input=>{let qty=Math.max(0,Number(input.value)||0);if(qty>0){let sub=qty*Number(input.dataset.price);total+=sub;lines.push(`<div class="flex justify-between gap-3"><span class="text-zinc-300">${input.dataset.title} × ${qty}</span><span>${money(sub)}</span></div>`)}});document.getElementById('cartLines').innerHTML=lines.length?lines.join(''):'<p class="text-zinc-500">Belum ada barang dipilih.</p>';document.getElementById('cartTotal').textContent=money(total)}document.querySelectorAll('.qty').forEach(el=>el.addEventListener('input',updateCart));document.getElementById('partsForm').addEventListener('submit',e=>{if(![...document.querySelectorAll('.qty')].some(el=>Number(el.value)>0)){e.preventDefault();alert('Pilih minimal satu sparepart terlebih dahulu.')}});
</script></body></html>
